export type ApiProblem = {
    /**
     * Stable problem type for capability failures; omitted means RFC 9457 `about:blank`.
     */
    type?: string;
    /**
     * Short human-readable problem category.
     */
    title: string;
    /**
     * HTTP status code.
     */
    status: number;
    /**
     * Safe human-readable fallback detail.
     */
    detail: string;
    /**
     * Request path that produced the problem.
     */
    instance: string;
    /**
     * Stable capability-prefixed code; present only for expected capability failures.
     */
    code?: string;
    /**
     * Field validation failures with safe allowlisted parameters; no rejected values.
     */
    errors?: Array<{
        field: string;
        /**
         * Compatible fallback message; clients localize by code.
         */
        message: string;
        code: 'REQUIRED' | 'INVALID' | 'EMAIL' | 'SIZE' | 'MIN' | 'MAX';
        params: {
            min?: number;
            max?: number;
        };
    }>;
};

